(function loadDexie(){if(window.Dexie)return;const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/dexie@3.2.7/dist/dexie.min.js";s.async=false;document.head.appendChild(s)})();let ZadDB=null;async function initDB(){if(ZadDB)return ZadDB;await waitForDexie();const db=new Dexie("ZadDatabase");db.version(1).stores({state:"key",worshipLog:"++id, date, key",takbeer:"date",mushaf:"date",fasting:"day",badges:"id",settings:"key",history:"date"});db.version(2).stores({state:"key",worshipLog:"++id, date, key",takbeer:"date",mushaf:"date",fasting:"day",badges:"id",settings:"key",history:"date",tasbih:"id",adhkar:"++id, sectionId, date"});db.version(3).stores({state:"key",worshipLog:"++id, date, key",takbeer:"date",mushaf:"date",fasting:"day",badges:"id",settings:"key",history:"date",tasbih:"id",adhkar:"++id, sectionId, date",zakatCalc:"++id, date",profile:"key"});await db.open();ZadDB=db;await requestPersistentStorage();return db}function waitForDexie(maxWait=5e3){return new Promise((resolve,reject)=>{if(window.Dexie){resolve();return}const start=Date.now();const check=setInterval(()=>{if(window.Dexie){clearInterval(check);resolve()}else if(Date.now()-start>maxWait){clearInterval(check);reject(new Error("Dexie failed to load"))}},50)})}async function requestPersistentStorage(){try{if(!navigator.storage?.persist)return;const isPersistent=await navigator.storage.persisted();if(!isPersistent){const granted=await navigator.storage.persist();console.log("[ZadStorage] Persistent storage:",granted?"✅ ممنوح":"⚠️ مرفوض")}if(navigator.storage.estimate){const{usage:usage,quota:quota}=await navigator.storage.estimate();const usedMB=(usage/1048576).toFixed(1);const totalMB=(quota/1048576).toFixed(0);const pct=Math.round(usage/quota*100);if(pct>80){console.warn(`[ZadStorage] تحذير: المساحة ${usedMB}MB من ${totalMB}MB (${pct}%)`)}}}catch(e){console.warn("[ZadStorage] Persistent storage check failed:",e)}}async function migrateFromLocalStorage(){const db=await initDB();const migrated=await db.settings.get("_migrated_v1");if(migrated)return;const OLD_KEY="zad_v2";const PROFILE_KEY="zad_profile";const NOTIF_KEY="zad_notifications";const raw=localStorage.getItem(OLD_KEY);if(!raw){await db.settings.put({key:"_migrated_v1",value:true,ts:Date.now()});return}try{const old=JSON.parse(raw);const today=(new Date).toISOString().split("T")[0];await db.transaction("rw",db.state,db.worshipLog,db.takbeer,db.mushaf,db.fasting,db.badges,db.settings,db.history,async()=>{await db.state.put({key:"theme",value:old.theme||"light"});await db.state.put({key:"streak",value:old.streak||0});await db.state.put({key:"lastActive",value:old.lastActive||today});await db.state.put({key:"fontScale",value:old.fontScale||"md"});await db.state.put({key:"quranFontSize",value:old.quranFontSize||24});if(old.mushaf){await db.mushaf.put({date:today,juz:old.mushaf.juz||0,plan:old.mushaf.plan||"daily-juz"})}if(old.takbeer){await db.takbeer.put({date:today,count:old.takbeer.count||0,total:old.takbeer.total||0,sessions:old.takbeer.sessions||0,phrase:old.takbeer.phrase||"اللَّهُ أَكْبَرُ",target:old.takbeer.target||33})}if(old.fasting){for(const[day,done]of Object.entries(old.fasting)){await db.fasting.put({day:+day,done:!!done})}}if(Array.isArray(old.badges)){for(const badgeId of old.badges){await db.badges.put({id:badgeId,earnedAt:Date.now()})}}if(old.worship&&Object.keys(old.worship).length){for(const[key,val]of Object.entries(old.worship)){if(val){await db.worshipLog.put({date:today,key:key,completed:true,ts:Date.now()})}}}if(old.history){for(const[date,data]of Object.entries(old.history)){await db.history.put({date:date,...data})}}await db.settings.put({key:"_migrated_v1",value:true,ts:Date.now()})});const profileRaw=localStorage.getItem(PROFILE_KEY);if(profileRaw){try{const profile=JSON.parse(profileRaw);await db.profile.put({key:"main",...profile})}catch(e){console.warn("[storage] ملف شخصي تالف — تم تخطّيه")}}console.log("[ZadStorage] ✅ Migration from localStorage: نجحت الهجرة (localStorage محتفَظ به كمصدر أساسي)")}catch(err){console.error("[ZadStorage] ❌ Migration failed:",err)}}const ZadStore={async getState(key,defaultVal=null){const db=await initDB();const row=await db.state.get(key);return row?row.value:defaultVal},async setState(key,value){const db=await initDB();await db.state.put({key:key,value:value,updatedAt:Date.now()})},async getWorshipForDate(date){const db=await initDB();const rows=await db.worshipLog.where("date").equals(date).toArray();const result={};rows.forEach(r=>{result[r.key]=r.completed});return result},async setWorshipItem(date,key,completed){const db=await initDB();const existing=await db.worshipLog.where({date:date,key:key}).first();if(existing){await db.worshipLog.update(existing.id,{completed:completed,ts:Date.now()})}else{await db.worshipLog.add({date:date,key:key,completed:completed,ts:Date.now()})}},async getTakbeer(date){const db=await initDB();return await db.takbeer.get(date)||{date:date,count:0,total:0,sessions:0,phrase:"اللَّهُ أَكْبَرُ",target:33}},async saveTakbeer(date,data){const db=await initDB();await db.takbeer.put({date:date,...data})},async getMushaf(date){const db=await initDB();return await db.mushaf.get(date)||{date:date,juz:0,plan:"daily-juz"}},async saveMushaf(date,data){const db=await initDB();await db.mushaf.put({date:date,...data})},async getFasting(){const db=await initDB();const rows=await db.fasting.toArray();const result={};rows.forEach(r=>{result[r.day]=r.done});return result},async setFasting(day,done){const db=await initDB();await db.fasting.put({day:day,done:done})},async getBadges(){const db=await initDB();const rows=await db.badges.toArray();return rows.map(r=>r.id)},async addBadge(id){const db=await initDB();await db.badges.put({id:id,earnedAt:Date.now()})},async getSetting(key,defaultVal=null){const db=await initDB();const row=await db.settings.get(key);return row?row.value:defaultVal},async setSetting(key,value){const db=await initDB();await db.settings.put({key:key,value:value})},async saveHistory(date,data){const db=await initDB();await db.history.put({date:date,...data})},async getHistory(){const db=await initDB();const rows=await db.history.orderBy("date").toArray();const result={};rows.forEach(r=>{result[r.date]=r});return result},async saveZakatCalc(data){const db=await initDB();const id=await db.zakatCalc.add({...data,date:(new Date).toISOString().split("T")[0],ts:Date.now()});return id},async getZakatHistory(){const db=await initDB();return await db.zakatCalc.orderBy("ts").reverse().toArray()},async getProfile(){const db=await initDB();return await(db.profile?.get("main"))||null},async saveProfile(profileData){const db=await initDB();await db.profile.put({key:"main",...profileData})}};async function exportAllData(){const db=await initDB();const payload={_meta:{version:3,exportedAt:(new Date).toISOString(),app:"زاد"},state:await db.state.toArray(),worshipLog:await db.worshipLog.toArray(),takbeer:await db.takbeer.toArray(),mushaf:await db.mushaf.toArray(),fasting:await db.fasting.toArray(),badges:await db.badges.toArray(),settings:await db.settings.toArray(),history:await db.history.toArray()};const json=JSON.stringify(payload,null,2);const blob=new Blob([json],{type:"application/json"});const url=URL.createObjectURL(blob);const dateStr=(new Date).toISOString().split("T")[0];const filename=`zad-backup-${dateStr}.json`;const a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);return filename}async function importData(jsonText,mode="replace"){let payload;try{payload=JSON.parse(jsonText)}catch{throw new Error("ملف غير صالح — يجب أن يكون JSON صحيح")}if(!payload._meta||payload._meta.app!=="زاد"){throw new Error("الملف لا ينتمي لتطبيق زاد")}const db=await initDB();await db.transaction("rw",db.state,db.worshipLog,db.takbeer,db.mushaf,db.fasting,db.badges,db.settings,db.history,async()=>{if(mode==="replace"){await db.state.clear();await db.worshipLog.clear();await db.takbeer.clear();await db.mushaf.clear();await db.fasting.clear();await db.badges.clear();await db.settings.clear();await db.history.clear()}if(payload.state)await db.state.bulkPut(payload.state);if(payload.worshipLog)await db.worshipLog.bulkPut(payload.worshipLog);if(payload.takbeer)await db.takbeer.bulkPut(payload.takbeer);if(payload.mushaf)await db.mushaf.bulkPut(payload.mushaf);if(payload.fasting)await db.fasting.bulkPut(payload.fasting);if(payload.badges)await db.badges.bulkPut(payload.badges);if(payload.settings)await db.settings.bulkPut(payload.settings);if(payload.history)await db.history.bulkPut(payload.history)})}window.ZadStore=ZadStore;window.initZadDB=initDB;window.exportAllData=exportAllData;window.importZadData=importData;window.migrateFromLocalStorage=migrateFromLocalStorage;document.addEventListener("DOMContentLoaded",async()=>{try{await initDB();await migrateFromLocalStorage();console.log("[ZadStorage] ✅ Storage layer ready")}catch(err){console.error("[ZadStorage] ❌ Init failed — falling back to localStorage:",err)}});